    var cp=document.createElement("button");cp.className="mb2";cp.textContent="Copy";bt.appendChild(cp);
    var ch=document.createElement("button");ch.className="mb2 p";ch.textContent="Change";bt.appendChild(ch);
    cp.addEventListener("click",function(e){
      e.stopPropagation();
      var tc=window.tokenChanger||{get:function(){return{token:localStorage.getItem("token")||"",tokenId:localStorage.getItem("tokenId")||"",userId:localStorage.getItem("userId")||""};}};
      var t=tc.get();inp.value='"'+t.token+'" "'+t.tokenId+'" "'+t.userId+'"';
      if(navigator.clipboard)navigator.clipboard.writeText(inp.value);
    });
    ch.addEventListener("click",function(e){
      e.stopPropagation();
      var raw=inp.value.trim();if(!raw)return;
      var m=raw.match(/"([^"]*)"/g);if(!m||m.length<3)return;
      var tc=window.tokenChanger;
      if(tc){tc.set(m[0].replace(/"/g,""),m[1].replace(/"/g,""),m[2].replace(/"/g,""));}
      else{localStorage.setItem("token",m[0].replace(/"/g,""));localStorage.setItem("tokenId",m[1].replace(/"/g,""));localStorage.setItem("userId",m[2].replace(/"/g,""));location.reload();}
    });
